#include "ggml.h"
#include "ggml-cpu.h"
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
static enum ggml_type types[]={GGML_TYPE_Q4_K,GGML_TYPE_Q5_K,GGML_TYPE_Q6_K,GGML_TYPE_Q3_K,GGML_TYPE_Q2_K,GGML_TYPE_IQ4_XS,GGML_TYPE_IQ2_XXS,GGML_TYPE_IQ2_XS,GGML_TYPE_IQ2_S,GGML_TYPE_IQ3_XXS,GGML_TYPE_IQ3_S,GGML_TYPE_IQ1_S,GGML_TYPE_IQ1_M};
static const int dpos[]={0,0,208,108,80,0,0,0,0,0,0,0,-1};
static const int dmpos[]={2,2,-1,-1,82,-1,-1,-1,-1,-1,-1,-1,-1};
static uint32_t rng=20261107;
static uint32_t next(void){rng=rng*1664525u+1013904223u;return rng;}
static float random_value(void){return ((int32_t)(next()>>8)-8388608)*0.0000003f;}
static struct ggml_threadpool*pools[3];static uint64_t cases,values;
extern void quantize_row_q8_K(const float*,void*,int64_t);
static void fill_weights(struct ggml_tensor*w,int kind,int pattern){size_t n=ggml_nbytes(w),bs=ggml_type_size(w->type);uint8_t*p=w->data;for(size_t i=0;i<n;++i)p[i]=pattern==1?0:pattern==2?255:(uint8_t)(next()>>24);for(size_t b=0;b<n/bs;++b){uint16_t d=pattern==1?0:b%2?0xb000:0x2c00;if(kind==12){for(int j=0;j<4;++j){uint16_t sc;memcpy(&sc,p+b*bs+48+2*j,2);sc=(sc&4095)|(((d>>(4*j))&15)<<12);memcpy(p+b*bs+48+2*j,&sc,2);}}else{memcpy(p+b*bs+dpos[kind],&d,2);if(dmpos[kind]>=0){uint16_t dm=pattern==1?0:0x2800;memcpy(p+b*bs+dmpos[kind],&dm,2);}}}}
static struct ggml_tensor*input(struct ggml_context*ctx,int width,int n1,int n2,int n3,int pad,int quant,int zero){
 struct ggml_tensor*storage=ggml_new_tensor_4d(ctx,GGML_TYPE_F32,width+(pad?16:0),n1,n2,n3);for(int64_t i=0;i<ggml_nelements(storage);++i)((float*)storage->data)[i]=zero?0.0f:random_value();
 struct ggml_tensor*y=pad?ggml_view_4d(ctx,storage,width,n1,n2,n3,storage->nb[1],storage->nb[2],storage->nb[3],0):storage;
 if(quant){struct ggml_tensor*qs=ggml_new_tensor_4d(ctx,GGML_TYPE_Q8_K,width+(pad?256:0),n1,n2,n3);struct ggml_tensor*q=pad?ggml_view_4d(ctx,qs,width,n1,n2,n3,qs->nb[1],qs->nb[2],qs->nb[3],0):qs;for(int i3=0;i3<n3;++i3)for(int i2=0;i2<n2;++i2)for(int i1=0;i1<n1;++i1)quantize_row_q8_K((const float*)((char*)y->data+i3*y->nb[3]+i2*y->nb[2]+i1*y->nb[1]),(char*)q->data+i3*q->nb[3]+i2*q->nb[2]+i1*q->nb[1],width);y=q;}
 return y;
}
static void compute(struct ggml_context*ctx,struct ggml_tensor*out,int pool,FILE*f){struct ggml_cgraph*g=ggml_new_graph_custom(ctx,64,false);ggml_build_forward_expand(g,out);int threads[]={1,2,8};struct ggml_cplan plan=ggml_graph_plan(g,threads[pool],pools[pool]);plan.work_data=malloc(plan.work_size);if(plan.work_size&&!plan.work_data)abort();memset(out->data,0xa5,ggml_nbytes(out));if(ggml_graph_compute(g,&plan)!=GGML_STATUS_SUCCESS)abort();size_t size=ggml_nbytes(out);void*expected=malloc(size);if(!expected)abort();memcpy(expected,out->data,size);
for(int warm=0;warm<2;++warm)if(ggml_graph_compute(g,&plan)!=GGML_STATUS_SUCCESS)abort();
for(int round=0;round<5;++round){int64_t begin=ggml_time_us();for(int repeat=0;repeat<5;++repeat)if(ggml_graph_compute(g,&plan)!=GGML_STATUS_SUCCESS)abort();double us=(ggml_time_us()-begin)/5.0;if(memcmp(expected,out->data,size))abort();printf("{\"kind\":\"operation\",\"case\":%llu,\"op\":%d,\"type\":%d,\"width\":%lld,\"output\":%lld,\"rows\":%lld,\"threads\":%d,\"round\":%d,\"microseconds\":%.9g}\n",(unsigned long long)cases,out->op,out->src[0]->type,(long long)out->src[0]->ne[0],(long long)out->ne[0],(long long)out->ne[1],threads[pool],round,us);}free(expected);uint64_t bytes=ggml_nbytes(out);if(fwrite(&bytes,8,1,f)!=1||fwrite(out->data,1,bytes,f)!=bytes)abort();cases++;values+=ggml_nelements(out);free(plan.work_data);}
static void dense(int kind,int profile,FILE*f){int widths[]={256,768,2560,4352},rows[]={17,65,129,257},columns[]={8,17,7,273};int width=widths[profile],nr=rows[profile],nc=columns[profile],n02=profile==1?2:1,n03=profile==2?2:1,n12=profile==1?4:profile==2?2:1,n13=profile==1?2:profile==2?4:1;int pad=profile%2,quant=profile>=2;struct ggml_context*ctx=ggml_init((struct ggml_init_params){64u*1024*1024,NULL,false});if(!ctx)abort();struct ggml_tensor*ws=ggml_new_tensor_4d(ctx,types[kind],width+(pad?256:0),nr,n02,n03);fill_weights(ws,kind,0);struct ggml_tensor*w=pad?ggml_view_4d(ctx,ws,width,nr,n02,n03,ws->nb[1],ws->nb[2],ws->nb[3],0):ws;struct ggml_tensor*y=input(ctx,width,nc,n12,n13,pad,quant,profile==3&&kind%3==0);struct ggml_tensor*out=ggml_mul_mat(ctx,w,y);compute(ctx,out,profile%3,f);ggml_free(ctx);}
static void moe(int kind,int profile,FILE*f){int widths[]={512,1280,2048,4096},rows[]={17,65,129,257},tokens[]={8,16,17,273},slots[]={1,2,4,2};int width=widths[profile],nr=rows[profile],nt=tokens[profile],ns=slots[profile],experts=profile==2?17:5,pad=profile%2;struct ggml_context*ctx=ggml_init((struct ggml_init_params){64u*1024*1024,NULL,false});if(!ctx)abort();struct ggml_tensor*ws=ggml_new_tensor_3d(ctx,types[kind],width+(pad?256:0),nr,experts);fill_weights(ws,kind,0);struct ggml_tensor*w=pad?ggml_view_3d(ctx,ws,width,nr,experts,ws->nb[1],ws->nb[2],0):ws;struct ggml_tensor*y=input(ctx,width,ns,nt,1,pad,profile==2,profile==3&&kind%3==0);struct ggml_tensor*ids=ggml_new_tensor_2d(ctx,GGML_TYPE_I32,4,nt);for(int t=0;t<nt;++t)for(int j=0;j<4;++j)((int32_t*)ids->data)[t*4+j]=j;struct ggml_tensor*out=ggml_mul_mat_id(ctx,w,y,ids);compute(ctx,out,profile%3,f);ggml_free(ctx);}
int main(int argc,char**argv){if(argc!=2)return 2;ggml_cpu_init();int threads[]={1,2,8};for(int i=0;i<3;++i){struct ggml_threadpool_params p=ggml_threadpool_params_default(threads[i]);p.poll=0;pools[i]=ggml_threadpool_new(&p);if(!pools[i])abort();}FILE*f=fopen(argv[1],"wb");if(!f)return 3;for(int kind=0;kind<13;++kind)for(int p=0;p<4;++p){dense(kind,p,f);moe(kind,p,f);}fclose(f);for(int i=0;i<3;++i)ggml_threadpool_free(pools[i]);printf("{\"graphs\":%llu,\"values\":%llu,\"dense\":52,\"moe\":52,\"formats\":13}\n",(unsigned long long)cases,(unsigned long long)values);return 0;}
